import {
  ZOOM_IN_FACTOR,
  ZOOM_OUT_FACTOR,
  getZoomStep,
} from '../../core/functions/zoom.js';

/**
 * Calculates the next domain.
 * @param zoomState - The type of zoom for the next step.
 * @param currentDomain - The current domain of the chart.
 * @param cursorXPoint - x coordinate taken from the mouse cursor to calculate the center point for the zoom
 * @returns The next domain.
 */
function getNextDomain(
  zoomState: string,
  currentDomain: number[],
  cursorXPoint?: number,
) {
  const factor = zoomState === 'zoom-in' ? ZOOM_IN_FACTOR : ZOOM_OUT_FACTOR;

  const totalScale = currentDomain[1] - currentDomain[0];

  const offsetMin =
    (cursorXPoint ? cursorXPoint - currentDomain[0] : totalScale) * factor;
  const offsetMax =
    (cursorXPoint ? currentDomain[1] - cursorXPoint : totalScale) * factor;

  const nextDomain =
    zoomState === 'zoom-in'
      ? [currentDomain[0] + offsetMin, currentDomain[1] - offsetMax]
      : [currentDomain[0] - offsetMin, currentDomain[1] + offsetMax];

  return nextDomain;
}

export function getHistogramZoomStep(
  initialDomain: number[],
  currentDomain: number[],
  zoomState: string,
  cursorXPoint?: number,
) {
  const nextDomain = getNextDomain(zoomState, currentDomain, cursorXPoint);
  const { newDomain, isMinZoom, isMaxZoom } = getZoomStep(
    initialDomain,
    currentDomain,
    nextDomain,
  );

  return { newDomain: newDomain as number[], isMinZoom, isMaxZoom };
}
